import{o as e,s as t}from"./chunks/canvas_utils.BhIhmoFR.js";import{It as n,Q as r,ht as i,it as a,nt as o,rt as s,tt as c}from"./chunks/framework.Cs5aHXsR.js";import{n as l,t as u}from"./chunks/canvas_pbr.N-SheeM6.js";var d=JSON.parse(`{"title":"Shaders e Linguagens de Sombreamento","description":"O que são Shaders, linguagens (GLSL, HLSL, WGSL, MSL), pipelines programáveis e demonstrações interativas.","frontmatter":{"title":"Shaders e Linguagens de Sombreamento","sidebar_label":"Shaders","description":"O que são Shaders, linguagens (GLSL, HLSL, WGSL, MSL), pipelines programáveis e demonstrações interativas."},"headers":[],"relativePath":"shaders.md","filePath":"shaders.md","lastUpdated":1789310783000}`),f=Object.assign({name:`shaders.md`},{setup(d){return(d,f)=>(i(),c(`div`,null,[f[0]||=o(`<h1 id="shaders-e-programacao-grafica" tabindex="-1">Shaders e Programação Gráfica <a class="header-anchor" href="#shaders-e-programacao-grafica" aria-label="Permalink to “Shaders e Programação Gráfica”">​</a></h1><blockquote><p>Um <strong>Shader</strong> (sombreamento) é um pequeno programa escrito para ser executado diretamente nos milhares de núcleos paralelos da GPU. Eles controlam como cada vértice é transformado no espaço e qual cor cada pixel final recebe na tela.</p></blockquote><p>Antes dos anos 2000, as placas de vídeo possuíam pipelines de função fixa (<em>fixed-function pipeline</em>): o desenvolvedor só podia ligar ou desligar parâmetros pré-definidos. Hoje, todo o pipeline gráfico é programável através de shaders.</p><h2 id="demonstracoes-interativas" tabindex="-1">Demonstrações Interativas <a class="header-anchor" href="#demonstracoes-interativas" aria-label="Permalink to “Demonstrações Interativas”">​</a></h2><h3 id="_1-vertex-fragment-shader-em-tempo-real" tabindex="-1">1. Vertex &amp; Fragment Shader em Tempo Real <a class="header-anchor" href="#_1-vertex-fragment-shader-em-tempo-real" aria-label="Permalink to “1. Vertex &amp; Fragment Shader em Tempo Real”">​</a></h3><p>Abaixo combinamos a visualização tridimensional interativa (com deformação de vértices e cálculo de cor em tempo real na GPU) com o diagrama didático 2D do trânsito de dados através do pipeline gráfico.</p>`,6),a(e,{topic:`shaders`,title:`Visualização 3D de Shaders na GPU`,subtitle:`Deformação senoidal contínua de vértices (Vertex Shader) e coloração dinâmica por fragmento.`}),a(t,{sketch:n(l),title:`Diagrama Didático 2D: Fluxo do Pipeline Programável`,subtitle:`Vértices de Entrada → Vertex Shader → Rasterizador → Fragment Shader → Pixels na Tela.`},null,8,[`sketch`]),f[1]||=r(`h3`,{id:`_2-shaders-de-materiais-pbr-physically-based-rendering`,tabindex:`-1`},[s(`2. Shaders de Materiais PBR (Physically Based Rendering) `),r(`a`,{class:`header-anchor`,href:`#_2-shaders-de-materiais-pbr-physically-based-rendering`,"aria-label":`Permalink to “2. Shaders de Materiais PBR (Physically Based Rendering)”`},`​`)],-1),f[2]||=r(`p`,null,`Shaders modernos calculam interações da luz com propriedades físicas reais da matéria (como rugosidade e metalicidade). Interaja com a matriz de esferas 3D abaixo e compare com o modelo esquemático microfacetário.`,-1),a(e,{topic:`pbr`,title:`Matriz 3D de Esferas PBR`,subtitle:`Superfícies dielétricas e metálicas sob luz pontual móvel revelando reflexão difusa vs especular.`}),a(t,{sketch:n(u),title:`Diagrama Didático 2D: Parâmetros PBR`,subtitle:`Variação controlada de Roughness (eixo vertical) e Metalness (eixo horizontal).`},null,8,[`sketch`]),f[3]||=o(`<hr><h2 id="tipos-de-shaders-no-pipeline-moderno" tabindex="-1">Tipos de Shaders no Pipeline Moderno <a class="header-anchor" href="#tipos-de-shaders-no-pipeline-moderno" aria-label="Permalink to “Tipos de Shaders no Pipeline Moderno”">​</a></h2><table tabindex="0"><thead><tr><th>Tipo de Shader</th><th>Estágio</th><th>O que processa</th><th>Exemplo de Aplicação</th></tr></thead><tbody><tr><td><strong>Vertex Shader</strong></td><td>Entrada de Geometria</td><td>Vértice individual</td><td>Transformação de coordenadas (matriz MVP), animação de esqueletos (skinning), ondas no mar</td></tr><tr><td><strong>Tessellation Shader</strong></td><td>Subdivisão</td><td>Primitivas poligonais</td><td>Adição dinâmica de detalhes geométricos conforme proximidade da câmera (LOD)</td></tr><tr><td><strong>Geometry Shader</strong></td><td>Pós-Vértices</td><td>Primitivas inteiras (triângulos/linhas)</td><td>Geração de partículas, wireframe, silhuetas e prismas volumétricos</td></tr><tr><td><strong>Fragment / Pixel Shader</strong></td><td>Rasterização</td><td>Pixel / Fragmento individual</td><td>Cálculo de iluminação (Phong, PBR), texturização, reflexos, sombras e neblina</td></tr><tr><td><strong>Compute Shader</strong></td><td>Processamento Geral (GPGPU)</td><td>Dados arbitrários em buffers</td><td>Simulação de fluidos, física de partículas, inteligência artificial e culling</td></tr><tr><td><strong>Mesh Shader</strong></td><td>Pipeline de Próxima Geração</td><td>Meshlets (blocos de triângulos)</td><td>Substitui Vertex + Geometry Shaders com controle fino (adotado no DX12 Ultimate e Vulkan)</td></tr></tbody></table><hr><h2 id="as-grandes-linguagens-de-shader" tabindex="-1">As Grandes Linguagens de Shader <a class="header-anchor" href="#as-grandes-linguagens-de-shader" aria-label="Permalink to “As Grandes Linguagens de Shader”">​</a></h2><ul><li><a href="https://www.khronos.org/opengl/wiki/OpenGL_Shading_Language" target="_blank" rel="noreferrer">GLSL (OpenGL Shading Language)</a> — linguagem base do OpenGL e WebGL, sintaxe próxima de C — / <a href="https://registry.khronos.org/OpenGL/specs/gl/GLSLangSpec.4.60.pdf" target="_blank" rel="noreferrer">Spec PDF</a> / <a href="https://www.khronos.org/opengl/wiki/OpenGL_Shading_Language" target="_blank" rel="noreferrer">Wiki</a></li><li><a href="https://learn.microsoft.com/windows/win32/direct3dhlsl/dx-graphics-hlsl" target="_blank" rel="noreferrer">HLSL (High-Level Shading Language)</a> — linguagem proprietária da Microsoft para DirectX (D3D11, D3D12) e Xbox — / <a href="https://learn.microsoft.com/windows/win32/direct3dhlsl/dx-graphics-hlsl" target="_blank" rel="noreferrer">Documentação</a> / <a href="https://learn.microsoft.com/windows/win32/direct3dhlsl/dx-graphics-hlsl-reference" target="_blank" rel="noreferrer">Referência</a></li><li>🌐 <a href="https://www.w3.org/TR/WGSL/" target="_blank" rel="noreferrer">WGSL (WebGPU Shading Language)</a> — padrão da W3C para WebGPU no navegador, segura e fortemente tipada — / <a href="https://www.w3.org/TR/WGSL/" target="_blank" rel="noreferrer">Especificação</a> / <a href="https://google.github.io/tour-of-wgsl/" target="_blank" rel="noreferrer">Tour</a></li><li><a href="https://developer.apple.com/metal/Metal-Shading-Language-Specification.pdf" target="_blank" rel="noreferrer">MSL (Metal Shading Language)</a> — baseada em C++14, desenvolvida pela Apple para iOS, iPadOS e macOS — / <a href="https://developer.apple.com/metal/Metal-Shading-Language-Specification.pdf" target="_blank" rel="noreferrer">Spec PDF</a> / <a href="https://developer.apple.com/documentation/metal" target="_blank" rel="noreferrer">Documentação</a></li><li><a href="https://www.khronos.org/spir/" target="_blank" rel="noreferrer">SPIR-V</a> — representação intermediária binária da Khronos; recebe GLSL ou HLSL e gera um binário único para o driver consumir — / <a href="https://registry.khronos.org/SPIR-V/" target="_blank" rel="noreferrer">Especificação</a> / <a href="https://github.com/KhronosGroup/SPIRV-Tools" target="_blank" rel="noreferrer">GitHub Tools</a></li></ul><hr><h2 id="recursos" tabindex="-1">Recursos <a class="header-anchor" href="#recursos" aria-label="Permalink to “Recursos”">​</a></h2><h3 id="playgrounds-online-e-editores" tabindex="-1">Playgrounds Online e Editores <a class="header-anchor" href="#playgrounds-online-e-editores" aria-label="Permalink to “Playgrounds Online e Editores”">​</a></h3><ul><li><a href="https://www.shadertoy.com/" target="_blank" rel="noreferrer">Shadertoy</a> — / <a href="https://www.shadertoy.com/browse" target="_blank" rel="noreferrer">Explorar Shaders</a> / <a href="https://www.shadertoy.com/new" target="_blank" rel="noreferrer">Novo Shader</a> / <a href="https://www.shadertoy.com/howto" target="_blank" rel="noreferrer">Documentação</a> / <a href="https://www.shadertoy.com/" target="_blank" rel="noreferrer">Fórum</a></li><li><a href="https://glslsandbox.com/" target="_blank" rel="noreferrer">GLSL Sandbox</a> — editor minimalista de fragment shaders — / <a href="https://glslsandbox.com/" target="_blank" rel="noreferrer">Site</a> / <a href="https://github.com/mrdoob/glsl-sandbox" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://www.vertexshaderart.com/" target="_blank" rel="noreferrer">VertexShaderArt</a> — criação musical e visual com vertex shaders — / <a href="https://www.vertexshaderart.com/" target="_blank" rel="noreferrer">Site</a> / <a href="https://www.vertexshaderart.com/art" target="_blank" rel="noreferrer">Galeria</a></li><li><a href="https://compute.toys/" target="_blank" rel="noreferrer">ComputeToy</a> — playground para compute shaders WebGPU em tempo real — / <a href="https://compute.toys/" target="_blank" rel="noreferrer">Site</a> / <a href="https://github.com/compute-toy" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://webgpu.github.io/webgpu-samples/" target="_blank" rel="noreferrer">WebGPU Samples (Google)</a> — testador de WGSL e exemplos interativos no navegador — / <a href="https://webgpu.github.io/webgpu-samples/" target="_blank" rel="noreferrer">WebGPU Samples</a> / <a href="https://github.com/webgpu/webgpu-samples" target="_blank" rel="noreferrer">GitHub</a></li></ul><h3 id="livros-tutoriais-e-cursos" tabindex="-1">Livros, Tutoriais e Cursos <a class="header-anchor" href="#livros-tutoriais-e-cursos" aria-label="Permalink to “Livros, Tutoriais e Cursos”">​</a></h3><ul><li><a href="https://thebookofshaders.com/" target="_blank" rel="noreferrer">The Book of Shaders</a> — / <a href="https://thebookofshaders.com/" target="_blank" rel="noreferrer">Livro Online</a> / <a href="https://github.com/patriciogonzalezvivo/thebookofshaders" target="_blank" rel="noreferrer">GitHub</a> / <a href="https://thebookofshaders.com/glossary/" target="_blank" rel="noreferrer">Glossário GLSL</a> / <a href="https://github.com/patriciogonzalezvivo/thebookofshaders" target="_blank" rel="noreferrer">Exemplos</a></li><li><a href="https://iquilezles.org/articles/" target="_blank" rel="noreferrer">Inigo Quilez Articles</a> — matemática, SDF (Signed Distance Fields), ruído e iluminação — / <a href="https://iquilezles.org/articles/" target="_blank" rel="noreferrer">Artigos Técnicos</a> / <a href="https://iquilezles.org/articles/distfunctions/" target="_blank" rel="noreferrer">SDF 3D Functions</a> / <a href="https://www.youtube.com/@InigoQuilez" target="_blank" rel="noreferrer">YouTube</a></li><li><a href="https://learnopengl.com/Getting-started/Shaders" target="_blank" rel="noreferrer">LearnOpenGL: Shaders</a> — / <a href="https://learnopengl.com/Getting-started/Shaders" target="_blank" rel="noreferrer">Tutorial Básico</a> / <a href="https://learnopengl.com/PBR/Theory" target="_blank" rel="noreferrer">PBR Shading</a> / <a href="https://learnopengl.com/Guest-Articles/2022/Compute-Shaders/Introduction" target="_blank" rel="noreferrer">Compute Shaders</a></li><li><a href="https://www.ronja-tutorials.com/" target="_blank" rel="noreferrer">Ronja&#39;s Shader Tutorials</a> — shaders de alta qualidade em HLSL/Unity — / <a href="https://www.ronja-tutorials.com/" target="_blank" rel="noreferrer">Site</a></li><li><a href="https://catlikecoding.com/" target="_blank" rel="noreferrer">Catlike Coding: Custom SRP &amp; Shaders</a> — / <a href="https://catlikecoding.com/unity/tutorials/" target="_blank" rel="noreferrer">Tutoriais Unity/HLSL</a> / <a href="https://catlikecoding.com/unity/tutorials/rendering/" target="_blank" rel="noreferrer">Rendering Pipeline</a></li><li><a href="https://shader-learn.com/" target="_blank" rel="noreferrer">Shader-Learn</a> — plataforma interativa guiada para aprendizado de GLSL — / <a href="https://shader-learn.com/" target="_blank" rel="noreferrer">Site</a></li></ul><h3 id="ferramentas-compiladores-e-depuradores" tabindex="-1">Ferramentas, Compiladores e Depuradores <a class="header-anchor" href="#ferramentas-compiladores-e-depuradores" aria-label="Permalink to “Ferramentas, Compiladores e Depuradores”">​</a></h3><ul><li><a href="https://github.com/KhronosGroup/glslang" target="_blank" rel="noreferrer">glslang</a> — validador e compilador oficial de GLSL/HLSL para SPIR-V — / <a href="https://github.com/KhronosGroup/glslang" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://github.com/KhronosGroup/SPIRV-Cross" target="_blank" rel="noreferrer">SPIRV-Cross</a> — tradutor de SPIR-V para GLSL, HLSL, MSL e C++ — / <a href="https://github.com/KhronosGroup/SPIRV-Cross" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://github.com/gfx-rs/wgpu/tree/master/naga" target="_blank" rel="noreferrer">Naga (Rust)</a> — tradutor universal de shaders (WGSL, SPV, MSL, HLSL, GLSL) — / <a href="https://github.com/gfx-rs/wgpu" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://github.com/google/shaderc" target="_blank" rel="noreferrer">Shaderc (Google)</a> — pacote com wrappers em torno de glslang e spirv-tools — / <a href="https://github.com/google/shaderc" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://renderdoc.org/" target="_blank" rel="noreferrer">RenderDoc</a> — depurador gráfico profissional de frames e shaders — / <a href="https://renderdoc.org/" target="_blank" rel="noreferrer">Site</a> / <a href="https://github.com/baldurk/renderdoc" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://spector.babylonjs.com/" target="_blank" rel="noreferrer">Spector.js</a> — extensão de navegador para inspecionar comandos WebGL e shaders — / <a href="https://github.com/BabylonJS/Spector.js" target="_blank" rel="noreferrer">GitHub</a></li></ul><h3 id="comunidades-de-shaders" tabindex="-1">Comunidades de Shaders <a class="header-anchor" href="#comunidades-de-shaders" aria-label="Permalink to “Comunidades de Shaders”">​</a></h3><ul><li><a href="https://www.reddit.com/r/shaders/" target="_blank" rel="noreferrer">Reddit r/shaders</a> — / <a href="https://www.reddit.com/r/shaders/" target="_blank" rel="noreferrer">Comunidade</a></li><li><a href="https://www.reddit.com/r/shadertoy/" target="_blank" rel="noreferrer">Reddit r/shadertoy</a> — / <a href="https://www.reddit.com/r/shadertoy/" target="_blank" rel="noreferrer">Comunidade</a></li><li><a href="https://discord.gg/graphicsprogramming" target="_blank" rel="noreferrer">Discord Graphics Programming</a> — o maior servidor de programação gráfica do Discord</li></ul>`,16)]))}});export{d as __pageData,f as default};